// Flatten the QuickBooks Profit and Loss report into one row per line.
const r = $input.first().json;
const h = r.Header ?? {};
const lines = [];
const totals = {};
const num = v => (v === '' || v == null ? null : Number(v));

function walk(rows, section, level) {
  for (const row of rows ?? []) {
    if (row.type === 'Section' || row.Rows || row.Summary) {
      const title = row.Header?.ColData?.[0]?.value || section;
      if (row.Header) lines.push({ Section: section || title, Account: title, Amount: num(row.Header.ColData?.[1]?.value), Level: level, Type: 'Header' });
      walk(row.Rows?.Row, section || title, level + 1);
      if (row.Summary) {
        const [label, amt] = row.Summary.ColData ?? [];
        lines.push({ Section: section || title, Account: label?.value ?? '', Amount: num(amt?.value), Level: level, Type: 'Total' });
        if (row.group) totals[row.group] = num(amt?.value) ?? 0;
      }
    } else if (row.ColData) {
      const [label, amt] = row.ColData;
      lines.push({ Section: section, Account: label?.value ?? '', Amount: num(amt?.value), Level: level, Type: 'Line' });
    }
  }
}
walk(r.Rows?.Row, '', 0);

const money = v => (v < 0 ? '-$' : '$') + Math.abs(v ?? 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const forLlm = lines
  .filter(l => l.Amount !== null)
  .map(l => `${'  '.repeat(l.Level)}${l.Account}: ${money(l.Amount)}${l.Type === 'Total' ? ' (total)' : ''}`)
  .join('\n');

return [{ json: {
  start: h.StartPeriod, end: h.EndPeriod, currency: h.Currency ?? 'USD',
  income: totals.Income ?? 0, expenses: totals.Expenses ?? 0, netIncome: totals.NetIncome ?? 0,
  incomeText: money(totals.Income ?? 0), expensesText: money(totals.Expenses ?? 0), netText: money(totals.NetIncome ?? 0),
  lineCount: lines.length, lines, forLlm,
} }];

return $('Flatten P&L').first().json.lines.map(l => ({ json: {
  Section: l.Section,
  Account: '   '.repeat(l.Level) + l.Account,
  Amount: l.Amount,
  Type: l.Type,
} }));
